def page(path,title,description,body,active='',schema=None,zoom=False):
    canonical=f'<link rel="canonical" href="{E(SITE_URL+path)}">' if SITE_URL else ''
    data=json.dumps(schema,ensure_ascii=False).replace('<','\\u003c') if schema else ''
    structured=f'<script type="application/ld+json">{data}</script>' if schema else ''
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | KWS Hygiene</title><meta name="description" content="{E(description[:250])}"><meta name="robots" content="{"index,follow" if SITE_URL else "noindex,nofollow"}"><meta name="theme-color" content="#173e32"><meta property="og:title" content="{E(title)} | KWS Hygiene"><meta property="og:description" content="{E(description[:250])}"><meta property="og:type" content="website">{canonical}<link rel="icon" href="{E(logo['src'])}" type="image/webp"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script>{structured}</head><body>{header(active)}<main id="main">{body}</main>{footer()}{zoom_dialog() if zoom else ''}</body></html>'''
    target=OUT/(path.lstrip('/')+'index.html') if path.endswith('/') else OUT/path.lstrip('/')
    target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html);routes.append(path)
