# Preserve source URL access using generated redirects; production host can replace these with HTTP 301 rules.
def redirect(old,new):
    old=urlparse(old).path
    if not old or old=='/' or old==new:return
    target=OUT/old.lstrip('/');target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0;url={E(new)}"><title>Page moved | KWS</title><p>This page has moved. <a href="{E(new)}">Continue to KWS</a>.</p></html>');redirects.append((old,new))
for p in products:redirect(p['url'],p['path'])
for old,new in [('products.html','/products/'),('aboutus.html','/about/'),('factory.html','/manufacturing/'),('quality.html','/quality/'),('contactus.html','/contact/'),('contactnow.html','/contact/'),('video.html','/resources/'),('video-all.html','/resources/'),('video-playlist.html','/resources/'),('news.html','/news/'),('sitemap.html','/site-map/'),('privacy.html','/privacy/'),('cases/our-business-partners-1898.html','/about/partners/')]:redirect('/'+old,new)
for f in (ROOT/'research').glob('supplier-*.html'):
    b=BeautifulSoup(f.read_text(),'html.parser');name=b.h1.get_text(' ',strip=True) if b.h1 else ''
    if name in category_map:redirect('/'+f.stem,'/categories/'+category_map[name]['slug']+'/')
for v in resources['videos']:redirect(v['source'],f'/resources/v-{v["id"]}/')
for n in resources['news']:redirect(n['source'],'/news/team-building/')
with (CONTENT/'url-map.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['old_path','new_path']);w.writerows(redirects)
(OUT/'_redirects').write_text('\n'.join(f'{old} {new} 301' for old,new in redirects)+'\n')
(OUT/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Content-Security-Policy: default-src \'self\'; script-src \'self\'; style-src \'self\' \'unsafe-inline\'; img-src \'self\' data:; media-src \'self\' blob:; object-src \'none\'; base-uri \'self\'; frame-ancestors \'none\'\n')
(OUT/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nSitemap: '+SITE_URL+'/sitemap.xml\n' if SITE_URL else 'Disallow: /\n'))
if SITE_URL:
    (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+E(SITE_URL+p)+'</loc></url>' for p in routes if p!='/404.html')+'</urlset>')
else:(OUT/'sitemap.xml').unlink(missing_ok=True)
(CONTENT/'build-report.json').write_text(json.dumps({'pages':len(routes),'product_pages':len(products),'categories':len(categories),'certificates':len(certs),'certificate_scans':sum(len(c['scans']) for c in certs),'redirects':len(redirects),'production_url':SITE_URL or None,'routes':routes},indent=2))
print(f'Built {len(routes)} pages, {len(products)} products, {len(certs)} deduplicated document records, {len(redirects)} URL mappings.')
